{"command": "cd /tmp/sv-c96cb58857aa40df8f22be9ae3b68d5e/symbols
# nm sorted by address, find nearest function before target
aarch64-linux-gnu-nm -n libmonosgen-2.0.so.dbg 2>/dev/null | grep -i " [tT] " | awk '{print $1, $3}' | python3 -c "
import sys, bisect
syms = []
for line in sys.stdin:
    parts = line.strip().split()
    if len(parts) == 2:
        try:
            syms.append((int(parts[0], 16), parts[1]))
        except: pass
syms.sort()
addrs = [s[0] for s in syms]
for target in [0x2f4b20, 0x2f4c84]:
    idx = bisect.bisect_right(addrs, target) - 1
    if idx >= 0:
        print(f'0x{target:x}: {syms[idx][1]} + 0x{target - syms[idx][0]:x}')
"", "description": "Find function symbols near addresses"}
